releases:k=>{const r=RL.find(x=>x[0]==k);return {t:`${r[1]} ${r[2]}`,b:`<div class="fp-row" style="margin-bottom:14px">${r[8]}<span class="fp-tag">Tests ${r[5]}</span></div><h3 class="sub" style="font-weight:500;margin:0 0 8px">Changelog</h3><div class="fp-diff" style="font-size:14px">Proof of relationship checklist: <del>“at least 3 photos”</del> <ins>“photos across the relationship, with dates and places”</ins>. Added source: IRCC guide IMM 5289, page dated 12 Sep 2026.</div><h3 class="sub" style="font-weight:500;margin:16px 0 8px">Sign-off</h3>${STEPS([['Author',r[3]+' · 1 Oct','done'],['Tests',r[5]+' passing',r[5].split(' of ')[0]==r[5].split(' of ')[1]?'done':'now'],['Licensed reviewer',r[4],r[4]=='Waiting'||r[4]=='—'?'now':'done'],['Staged rollout',r[6],'']])}<h3 class="sub" style="font-weight:500;margin:16px 0 8px">Rollout to new matters</h3><div data-sl='{"min":0,"max":100,"step":5,"value":${parseInt(r[6])||0},"unit":"%","label":"New matters on this version"}'></div><p class="fp-note">Existing matters keep the version they pinned. 41 matters pinned to the previous version (demo).</p>`,f:`<button class="btn" data-close>Close</button><button class="btn" data-confirm-hold onclick="toast2('Rolled back',{sub:'New matters use the previous version. Pinned matters unchanged.'})">Hold to roll back</button>${RUN('Save rollout','Rollout saved',{sub:'Logged in Audit with your reason.'})}`}},
