 `<div class="mx"><div class="mxG4" style="grid-template-columns:repeat(3,1fr)">${kpi('#','users','Platform admins',empty?'1':'4','2FA on all','','1 owner · 2 admins · 1 reviewer','')}${kpi('#','mail','Pending invites',empty?'0':'1','expires 4 Nov','n','Invites last 7 days','')}${kpi('#','certificate','Licensed reviewers',empty?'0':'3','','','Can sign off template releases','')}</div>`+
 SEC('users','Team',empty?PAD(EMP('admin-calm','Only you so far','Invite the people who run Casevoya with you. Each one needs two-factor sign-in before their first visit.',BTN('Invite an admin',{p:1,ic:'user-plus',dlg:'mxInv'}))):
 TBL('Platform admins',['Person','Role','Licensed reviewer','Last sign-in','Security',''],AD.map(([k,n,e,r,rv,l,s])=>[`<span class="mxRow"><span class="mxAv">${n.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><span>${n}${k=='jr'?' <span class="fp-tag">You</span>':''}<small>${e}</small></span></span>`,r=='Owner'?BD('blue','Owner'):r,sw(rv,n),NUM(l),BD('ok',s),k=='jr'?'<span class="fp-note" style="margin:0">Owner can’t be removed</span>':`<button class="btn sm" onclick="mxRm('${n}')">${I('trash','s')}Remove</button>`])),BTN('Invite an admin',{p:1,ic:'user-plus',dlg:'mxInv'}))+
 (empty?'':SEC('mail','Pending invites',TBL('Pending invites',['Person','Role','Status',''],PI.map(([k,n,e,r,s])=>[`<span class="mxRow"><span class="mxAv" style="background:#f3f1ee;color:#6b6762">${n.split(' ').map(x=>x[0]).join('')}</span><span>${n}<small>${e}</small></span></span>`,r,BD('rev',s),`<span class="fp-row" style="gap:6px">${BTN('Resend',{toast:'Invite resent',sub:'New link sent to '+e+'. The old one stops working.'})}${BTN('Revoke',{toast:'Invite revoked',sub:'Logged in Audit.'})}</span>`]))))+
 `<div class="alert info">${I('info')}<div><b>Only @casevoya.ca addresses</b>Admins can see firm configuration and service data, never client files. Each removal is logged and signs the person out everywhere.</div></div></div>`+
 DLG('mxInv','Invite a Casevoya admin',`<div class="mx">${FLD('ivN','Full name',INP('ivN','','Daniel Nwosu'))}${FLD('ivE','Work email',INP('ivE','','name@casevoya.ca','email'),'Must be a @casevoya.ca address.')}${FLD('ivR','Role',SELECT('ivR',['Admin','Reviewer (template sign-off only)','Owner']))}<label class="mxRow" style="font-size:14px;margin-top:6px"><input type="checkbox"> Licensed reviewer (RCIC number checked separately)</label><p class="fp-note">The link works once and expires in 7 days. They must set up two-factor sign-in before they see anything.</p></div>`,`<button class="btn" onclick="closeDlg('mxInv')">Cancel</button><button class="btn p" onclick="const e=$('#ivE').value.trim();if(!/@casevoya\\.ca$/i.test(e)){toast2('Use a @casevoya.ca address',{kind:'bad',sub:'Firm staff are invited from inside their firm.'});return}closeDlg('mxInv');toast2('Invite sent to '+e,{kind:'ok',sub:'Shows under Pending invites.'})">${I('send','s')}Send invite</button>`)+
 DLG('mxRmD','Remove this admin?',`<div class="mx"><p style="margin:0 0 12px">You’re removing <b id="mxRmN"></b> from Casevoya platform administration.</p><ul class="mxChk"><li>${I('check-circle','s')}They’re signed out on every device straight away</li><li>${I('check-circle','s')}Any open support grants they hold are revoked</li><li>${I('check-circle','s')}Their past actions stay in Audit, unchanged</li></ul>${FLD('rmR','Reason (shown in Audit)',`<textarea class="ta" id="rmR" placeholder="Required"></textarea>`)}${FLD('rmC','Type REMOVE to confirm',INP('rmC','','REMOVE'))}</div>`,`<button class="btn" onclick="closeDlg('mxRmD')">Keep them</button><button class="btn p" style="background:#b42318;border-color:#b42318" onclick="if($('#rmC').value!='REMOVE'||!$('#rmR').value.trim()){toast2('Add a reason and type REMOVE',{kind:'bad'});return}closeDlg('mxRmD');toast2($('#mxRmN').textContent+' removed',{kind:'ok',sub:'Signed out everywhere. Logged in Audit.'})">${I('trash','s')}Remove admin</button>`);
