 DLG('mxRt','Retry a stuck message',`<div class="mx"><div class="mxStep"><span class="on" id="rs1"></span><span id="rs2"></span></div><div id="rtA"><p style="margin:0 0 4px;font-size:13px;color:#6b6762">Step 1 of 2 · Confirm it’s you</p><h3 class="mxH" style="margin:0 0 10px;font-weight:500">Enter the 6-digit code from your authenticator</h3><div class="mxOtp">${'<input inputmode="numeric" maxlength="1" aria-label="Digit">'.repeat(6)}</div><p class="fp-note">Required for every retry, even if you signed in recently. Or <a href="#" onclick="event.preventDefault();mxStep2()">use your passkey</a>.</p></div><div id="rtB" hidden><p style="margin:0 0 4px;font-size:13px;color:#6b6762">Step 2 of 2 · Confirm the retry</p><h3 class="mxH" style="margin:0 0 10px;font-weight:500" id="rtT"></h3>${DL([['Message','<span class="num" id="rtI"></span>'],['What happens','Sent once more to the same recipient. No content is shown to you.'],['If it fails again','It goes to dead letter and the firm gets a follow-up task.']])}${FLD('rtR','Reason (shown in Audit)',`<textarea class="ta" id="rtR" placeholder="e.g. Provider outage cleared at 13:40"></textarea>`)}</div></div>`,`<button class="btn" onclick="closeDlg('mxRt')">Cancel</button><button class="btn p" id="rtGo" onclick="mxRtGo()">Verify</button>`);
