// Own loading / empty / error states for the new screens
const OWN=['overview','admins','setup','health'];
const skel=()=>`<div class="mx" role="status" aria-busy="true"><span class="sr">Loading ${NM[TB]}…</span><div class="mxG4">${'<div class="mxC"><div class="mxSk" style="height:14px;width:50%"></div><div class="mxSk" style="height:30px;width:40%;margin-top:12px"></div><div class="mxSk" style="height:16px;margin-top:16px"></div></div>'.repeat(4)}</div><div class="mxG2"><div class="mxC"><div class="mxSk" style="height:210px"></div></div><div class="mxC"><div class="mxSk" style="height:210px"></div></div></div></div>`;
const prevL=AX_OWN.loading,prevE=AX_OWN.empty,prevErr=AX_OWN.error;
const BSK=`<div class="mxBoot mx"><div class="card" role="status" aria-busy="true"><span class="sr">Checking setup…</span><div class="mxSk" style="height:28px;width:45%"></div><div class="mxSk" style="height:34px;margin-top:22px"></div>${'<div class="mxSk" style="height:44px;margin-top:14px"></div>'.repeat(4)}</div></div>`;
const BER=`<div class="mxBoot mx"><div class="card"><div class="mxLogo"><img src="../../assets/brand/vo-mark-white.svg" alt="">Casevoya admin</div><h1>We couldn’t check setup</h1>${AX_ERR('The server didn’t answer','Request req_b0a2. No account was created. Try again in a moment.')}</div></div>`;
AX_OWN.loading=()=>{if(!OWN.includes(TB))return prevL?prevL():false;if(TB=='setup'){mxSO(BSK);return}$('#content').innerHTML=BAR+PH(NM[TB])+skel()};
AX_OWN.empty=()=>{if(!OWN.includes(TB))return prevE?prevE():false;if(TB=='setup'){mxSO(BOOT(false));return}if(TB=='health'){$('#content').innerHTML=BAR+PH('Service health','All services normal.')+`<div class="mx"><div class="mxC">${EMP('admin-calm','No stuck messages','Every email, reminder and export went out on its first or second try. Anything that gets stuck shows up here with a two-step retry.')}</div></div>`;fpBind($('#content'));return}
 $('#content').innerHTML=TB=='admins'?ADM(true).replace(/<dialog[\s\S]*$/,''):BAR+PH('Good morning, Jordan','No firms yet.')+`<div class="mx"><div class="mxC">${EMP('admin-calm','No firms on Casevoya yet','Charts fill in once the first firm signs up. Turn on sample mode to preview them with demo firms.',BTN('Open sample mode',{p:1,href:'sample-mode.html'}))}</div></div>`;fpBind($('#content'))};
AX_OWN.error=()=>{if(!OWN.includes(TB))return prevErr?prevErr():false;if(TB=='setup'){mxSO(BER);return}
 $('#content').innerHTML=BAR+PH(NM[TB])+AX_ERR(`We couldn’t load ${NM[TB].toLowerCase()}`,'The admin API didn’t answer (request req_8c71). Firms aren’t affected; nothing was changed.');fpBind($('#content'))};
